// Relative URLs intentionally use the document's directory, not the origin root.
const pending=new Map();
export async function json(url){if(!pending.has(url))pending.set(url,(async()=>{const r=await fetch(new URL(url,document.baseURI));if(!r.ok)throw Error(`${url}: HTTP ${r.status}`);if(url.endsWith('.gz')){const stream=r.body.pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text());}return r.json();})().catch(e=>{pending.delete(url);throw e;}));return pending.get(url);}
const readyCourses=new Set(),readyChapters=new Set(),readyLabs=new Set(),searches=new Map();
export const labData={questions:[],workedPrograms:[]};
export const seed=await json('./data/catalog.json');
export async function ensureCourse(id){const c=seed.courses.find(c=>c.id===id);if(!c?.catalog||readyCourses.has(id))return c;const meta=await json(c.catalog);Object.assign(c,structuredClone(meta));for(const key of ['questions','workedPrograms'])labData[key].push(...c._lab[key].filter(x=>!labData[key].some(y=>y.id===x.id&&y.courseId===id)));readyCourses.add(id);return c;}
export function assetURL(x){return typeof x==='object'&&x?.$asset?x.$asset:x;}
export async function ensureChapter(c,n){const key=c.id+'/'+n;if(readyChapters.has(key)||!c._chapters?.[n])return false;const chunk=await json(c._chapters[n]);const topics=new Map(chunk.topics.map(t=>[t.id,t]));c.topics=c.topics.map(t=>topics.has(t.id)?structuredClone(topics.get(t.id)):t);for(const k of ['teaching','examples','diagrams','lectures'])if(chunk[k])Object.assign(c[k],structuredClone(chunk[k]));if(chunk.listings){const m=new Map(chunk.listings.map(l=>[l.id,l]));c.series.listings=c.series.listings.map(l=>m.has(l.id)?structuredClone(m.get(l.id)):l);}readyChapters.add(key);return true;}
export async function ensureLabs(c){if(!c._coding||readyLabs.has(c.id))return;const x=await json(c._coding);for(const key of ['questions','workedPrograms']){const byId=new Map(x[key].map(q=>[q.id,q]));for(let i=0;i<labData[key].length;i++)if(labData[key][i].courseId===c.id&&byId.has(labData[key][i].id))labData[key][i]=structuredClone(byId.get(labData[key][i].id));}readyLabs.add(c.id);}
export async function ensureSearch(c){if(!c._search||searches.has(c.id))return;const parts=await Promise.all(c._search.map(json));searches.set(c.id,Object.assign({},...parts));}
export function searchMatch(c,t,q){return searches.get(c.id)?.[t.id]?.includes(q)??false;}
export async function restoreAssets(x){if(x?.$asset){const r=await fetch(new URL(x.$asset,document.baseURI));if(!r.ok)throw Error('Asset download failed');const a=new Uint8Array(await r.arrayBuffer());let text='';for(let i=0;i<a.length;i+=8192)text+=String.fromCharCode(...a.subarray(i,i+8192));return x.prefix+btoa(text);}if(Array.isArray(x))return Promise.all(x.map(restoreAssets));if(x&&typeof x==='object')return Object.fromEntries(await Promise.all(Object.entries(x).filter(([k])=>!k.startsWith('_')&&k!=='catalog').map(async([k,v])=>[k,await restoreAssets(v)])));return x;}
export async function completeCourse(c){await Promise.all(Object.keys(c._chapters||{}).map(n=>ensureChapter(c,n)));return restoreAssets(c);}
export async function downloadAsset(asset,name){const a=document.createElement('a');a.href=new URL(assetURL(asset),document.baseURI).href;a.download=name;document.body.append(a);a.click();a.remove();}
